import {escapeHTML as h} from './html.js';
const degree=p=>p.routes.some(r=>['college','graduate'].includes(r.key));
const keep=(p,education)=>education==='all'||p.routes.some(r=>education==='degree'?['college','graduate'].includes(r.key):r.key===education);
const names=rs=>rs.map(r=>h(r.title)).join(' · ')||'None';
export function broadEvaluationTable(rows,labels,education='all'){
 const paired=rows.filter(r=>r.broadReview);if(!paired.length)return '<p>No public evaluation records in this selection. Owner-only cases are excluded from this experiment.</p>';
 const groups=[['Selection total',paired],...Object.entries(labels).map(([id,label])=>[label,paired.filter(r=>r.phase===id)]).filter(([,rs])=>rs.length)];
 const pair=(rs,p)=>rs.filter(r=>p(r.broadReview.before.filter(x=>keep(x,education)))).length+' → '+rs.filter(r=>p(r.broadReview.after.filter(x=>keep(x,education)))).length;
 return '<p>Paired 0.50 → broader discovery pilot, using identical frozen answers. No new responses were inferred. Cohort and search filters select models; the education filter selects offers while retaining those model denominators, including models with no offer in that education group. Diagnostic variants enter only when selected; private cases have no paired evaluation.</p><div class="table-scroll" tabindex="0"><table><thead><tr><th>Cohort</th><th>Models</th><th>Any Top</th><th>College / graduate Top</th><th>Any Top covers lifestyle</th><th>First shown Top covers</th><th>Has unasked questions</th></tr></thead><tbody>'+groups.map(([label,rs])=>'<tr><th>'+h(label)+'</th><td>'+rs.length+'</td><td>'+pair(rs,t=>t.length>0)+'</td><td>'+pair(rs,t=>t.some(degree))+'</td><td>'+pair(rs,t=>t.some(p=>p.sustains===true))+'</td><td>'+pair(rs,t=>t[0]?.sustains===true)+'</td><td>'+rs.filter(r=>(r.broadReview.unaskedByEducation?.[education]||0)>0).length+'</td></tr>').join('')+'</tbody></table></div><p><strong>Result:</strong> routing alone does not create evidence or new Top matches. Unasked questions identify opportunities to investigate; their outcome is unmeasured until answered. Earlier expanded-degree reruns already explored every strongly aligned evidence-ready added profession. Historically reviewed holdouts are regression cohorts, not untouched accuracy validation.</p><p>Open a model below for its before/after Top list, broader invitations and the exact next questions. “Beyond three invitations” means additional discovery access, not a new confirmed match or proof the career was never shown.</p>';
}
export function broadEvaluationTrail(m,education='all'){
 const r=m.broadReview;if(!r)return '';
 const before=r.before.filter(p=>keep(p,education)),after=r.after.filter(p=>keep(p,education)),preview=r.preview.filter(p=>keep(p,education)),guided=r.newGuidedInvitations.filter(p=>keep(p,education)),questions=r.questionPreview.filter(q=>keep(q,education));
 return '<section class="coverage-release"><h3>Earlier routing-only evaluation · 0.51</h3><p><strong>Before · 0.50:</strong> '+names(before)+'</p><p><strong>Same answers · broader discovery:</strong> '+names(after)+'</p><p>The Top list was unchanged in that earlier routing-only comparison. All '+r.catalogSize+' catalog entries are considered for discovery without a chosen-field prerequisite. Candidate and question access passed the first-field invariance check for this model; this does not claim that every older matching rule is path independent.</p><p>'+r.open+' aligned possibilities remain open, '+r.declined+' have an explicitly declined defining interest, and '+r.uniqueUnasked+' distinct question IDs have not been answered across the open pool. These full-pool counts include all education routes.</p><p><a href="../student-view.html?case='+encodeURIComponent(m.id)+'&amp;replay=final#/journey/discover">Try broader discovery with this model’s current answers →</a></p><details><summary>Starting exploration cards · '+preview.length+'</summary>'+preview.map(p=>'<p><strong>'+h(p.title)+'</strong> · '+h(p.status)+' · '+h(p.routes.map(x=>x.label).join(' · '))+'</p>').join('')+'</details><details><summary>Guided possibilities beyond the current three invitations · '+guided.length+'</summary>'+guided.map(p=>'<article><h4>'+h(p.title)+'</h4><p>'+h(p.status)+'</p>'+p.questions.map(q=>'<p><strong>'+h(q.prompt)+'</strong><br>'+h(q.response)+(q.evidence?' · '+h(q.evidence):'')+'</p>').join('')+'</article>').join('')+'</details><details><summary>Up to 12 unasked-question previews · '+questions.length+' in this view</summary><p>Queue preview from the frozen state. A live round preserves this varied sequence, skips already answered or declined work, and recalculates for the next round. These are unasked questions, not invented model responses. Some existing prompts still describe work directly; this pilot tests routing and does not validate a rewritten questionnaire.</p>'+questions.map(q=>'<article><h4>'+h(q.prompt)+'</h4>'+(q.options?'<ul>'+q.options.map(o=>'<li>'+h(o.text)+'</li>').join('')+'</ul>':'')+'<p><strong>Unasked · no inferred response</strong></p></article>').join('')+(!questions.length?'<p>No unasked question in this preview. Existing unsure answers may still need a learning experience and direct clarification.</p>':'')+'</details></section>';
}
